function control(state) {
  var tip = state.tip, target = state.target;
  if (!tip || !target || !isFinite(tip[0]) || !isFinite(tip[1]) || !isFinite(target[0]) || !isFinite(target[1])) {
    return { action: "stop", reason: "invalid tip or target" };
  }
  var ex = target[0] - tip[0];
  var ey = target[1] - tip[1];
  var e = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(e)) return { action: "stop", reason: "non-finite error" };
  if (e <= state.tolerancePx) return { action: "verify" };

  var h = state.history || [];
  var n = h.length;
  var M = [[0, 0], [0, 0]];
  var B = [[0, 0], [0, 0]];
  for (var k = 0; k < n; k++) {
    var rec = h[k];
    if (!rec || !rec.delta || !isFinite(rec.delta[0]) || !isFinite(rec.delta[1])) continue;
    var c = (rec.applied && isFinite(rec.applied[0]) && isFinite(rec.applied[1])) ? rec.applied : rec.command;
    if (!c || !isFinite(c[0]) || !isFinite(c[1])) continue;
    if (Math.abs(c[0]) + Math.abs(c[1]) < 1e-9) continue;
    var w = (k + 1) / n;
    var d = rec.delta;
    for (var i = 0; i < 2; i++) {
      for (var j = 0; j < 2; j++) {
        M[i][j] += w * c[i] * c[j];
        B[i][j] += w * d[i] * c[j];
      }
    }
  }

  // choose probe sign for a channel: flip if the last probe on it was limited or produced no motion
  function probeSign(ch) {
    var sign = 1;
    for (var q = n - 1; q >= 0; q--) {
      var r = h[q];
      if (!r || !r.command || !isFinite(r.command[ch])) continue;
      var cc = r.command;
      if (Math.abs(cc[ch]) < 1e-9 || Math.abs(cc[1 - ch]) > 1e-9) continue;
      var s = cc[ch] > 0 ? 1 : -1;
      var ap = (r.applied && isFinite(r.applied[ch])) ? r.applied[ch] : 0;
      if (Math.abs(ap) < 0.5 * Math.abs(cc[ch]) || r.limited === true && Math.abs(ap) < 0.5 * Math.abs(cc[ch])) {
        sign = -s;
      } else {
        sign = s;
      }
      break;
    }
    return sign;
  }

  var probe = null;
  if (M[0][0] < 1e-4) {
    probe = [0.05 * probeSign(0), 0];
  } else if (M[1][1] < 1e-4) {
    probe = [0, 0.05 * probeSign(1)];
  }

  var u = null;
  if (!probe) {
    var mdet = M[0][0] * M[1][1] - M[0][1] * M[1][0];
    if (Math.abs(mdet) > 1e-9) {
      var Mi = [[M[1][1] / mdet, -M[0][1] / mdet], [-M[1][0] / mdet, M[0][0] / mdet]];
      var J = [[0, 0], [0, 0]];
      for (var r2 = 0; r2 < 2; r2++) {
        for (var s2 = 0; s2 < 2; s2++) {
          J[r2][s2] = B[r2][0] * Mi[0][s2] + B[r2][1] * Mi[1][s2];
        }
      }
      var jdet = J[0][0] * J[1][1] - J[0][1] * J[1][0];
      if (isFinite(jdet) && Math.abs(jdet) > 1e-6) {
        var Ji = [[J[1][1] / jdet, -J[0][1] / jdet], [-J[1][0] / jdet, J[0][0] / jdet]];
        u = [Ji[0][0] * ex + Ji[0][1] * ey, Ji[1][0] * ex + Ji[1][1] * ey];
      }
    }
    if (!u) {
      probe = [0, 0.05 * probeSign(1)];
    }
  }

  if (probe) {
    return { action: "move", u: probe };
  }

  var g = 0.6;
  u = [u[0] * g, u[1] * g];
  var mx = Math.max(Math.abs(u[0]), Math.abs(u[1]));
  if (!isFinite(mx)) return { action: "stop", reason: "non-finite control" };
  if (mx > 0.05) {
    u = [u[0] * 0.05 / mx, u[1] * 0.05 / mx];
  }
  if (mx < 1e-9) return { action: "stop", reason: "zero control" };
  return { action: "move", u: [u[0], u[1]] };
}
